chrome.runtime.onInstalled.addListener(()=>{chrome.contextMenus.create({id:"execute-blocks",title:"Execute Blocks",contexts:["editable"]})});chrome.contextMenus.onClicked.addListener((t,e)=>{t.menuItemId==="execute-blocks"&&(e!=null&&e.id)&&chrome.tabs.sendMessage(e.id,{action:"EXECUTE_BLOCKS"}).catch(c=>console.log("Could not send message, content script might not be loaded yet",c))});
